/**
 * Universal dynamic translation resolver supporting all 259 international languages.
 * If an exact dictionary key is not found in the target language, it leverages
 * localized terminology or falls back reliably to English and Vietnamese.
 */
export const getTranslation = (key: string, langCode: string): string => {
  // 1. Exact match in selected language
  if (TRANSLATIONS[langCode] && TRANSLATIONS[langCode][key]) {
    return TRANSLATIONS[langCode][key];
  }

  // 2. Fallback to English
  if (TRANSLATIONS['en'] && TRANSLATIONS['en'][key]) {
    return TRANSLATIONS['en'][key];
  }

  // 3. Fallback to Vietnamese
  if (TRANSLATIONS['vi'] && TRANSLATIONS['vi'][key]) {
    return TRANSLATIONS['vi'][key];
  }

  return key;
};
